#[derive(Clone,Debug)]struct Mark{at:usize,id:usize,before:bool,rev:bool,t:usize,acc:Vec<usize>,e:Vec<usize>,nm:Vec<usize>,shift:Vec<usize>,src:Vec<usize>}
#[derive(Clone)]struct Shot{batch:usize,lane:usize,v:[U256;6],old_bad:bool}
fn ids(s:&str)->Vec<usize>{if s=="-"{vec![]}else{s.split(',').map(|v|v.parse().unwrap()).collect()}}
fn marks()->Vec<Mark>{fs::read_to_string(format!("{ROOT}/fold-marks.tsv")).unwrap().lines().map(|l|{let f:Vec<_>=l.split('\t').collect();assert_eq!(f.len(),10);Mark{at:f[0].parse().unwrap(),id:f[1].parse().unwrap(),before:f[2]=="1",rev:f[3]=="1",t:f[4].parse().unwrap(),acc:ids(f[5]),e:ids(f[6]),nm:ids(f[7]),shift:ids(f[8]),src:ids(f[9])}}).collect()}
fn get(q:&[u64],ids:&[usize],lane:usize)->i128{assert!(ids.len()<64);ids.iter().enumerate().map(|(i,&qid)|(((q[qid]>>lane)&1)as i128)<<i).sum()}
fn calc(q:&[u64],a:&Mark,lane:usize)->(i128,i128,i128,i128,i128,i128){let l=get(q,&a.acc,lane);let e=get(q,&a.e,lane);let nm=get(q,&a.nm,lane);let shift=3+get(q,&a.shift,lane);let f=0x1000003d1i128;let sm=(1i128<<shift)-1;let digit=if a.rev{let b=get(q,&a.src,lane);assert_eq!(a.src.len(),6);let kr=(0..3).map(|i|((b^if nm>>i&1!=0{63}else{0})<<i)).sum::<i128>();(l-kr)&sm}else{let x=l+e+(e-nm)*(f-1);(0..=sm).find(|m|(m*f-x)&sm==0).unwrap()};let c=e+(e-nm+if a.rev{digit}else{-digit})*(f-1);let sum=l+c;let window=1i128<<a.acc.len();let carry=sum.div_euclid(window);(sum.rem_euclid(window),carry,l,e,nm,digit)}
fn main(){let started=Instant::now();let limit=std::env::args().nth(1).map(|v|v.parse().unwrap()).unwrap_or(4096usize);let workers=std::env::args().nth(2).map(|v|v.parse().unwrap()).unwrap_or(7usize);assert!(workers<=8);let audit=std::env::args().nth(3).as_deref()==Some("audit");let ops=Arc::new(load_ops(&format!("{ROOT}/raw-builder.bin")).unwrap());let finalops=Arc::new(load_ops("/home/hclau/ecdsa_research/product-exact-20261015/tip/ops.bin").unwrap());let marks=Arc::new(marks());let(nq,nb,_,regs)=analyze_ops(ops.iter());let(fnq,fnb,_,fregs)=analyze_ops(finalops.iter());assert_eq!(regs,fregs);let rows=if audit{fs::read_to_string("/home/hclau/ecdsa_research/payload-model-20261016/packets/audit.tsv").unwrap().lines().enumerate().map(|(lane,l)|{let v=l.split_whitespace().skip(1).map(|v|U256::from_str_radix(v.trim_start_matches("0x"),16).unwrap()).collect::<Vec<_>>().try_into().unwrap();Shot{batch:0,lane,v,old_bad:false}}).collect::<Vec<_>>()}else{fs::read_to_string("/home/hclau/ecdsa_research/prefilter-20261015/evidence/census-coordinates4096.tsv").unwrap().lines().skip(1).map(|l|{let f:Vec<_>=l.split_whitespace().collect();Shot{batch:f[0].parse().unwrap(),lane:f[1].parse().unwrap(),v:f[4..10].iter().map(|v|U256::from_str_radix(v.trim_start_matches("0x"),16).unwrap()).collect::<Vec<_>>().try_into().unwrap(),old_bad:f[10]!="0"}}).take(limit*64).collect::<Vec<_>>()};let rows=Arc::new(rows);let batches=rows.len().div_ceil(64);let next=AtomicUsize::new(0);let run=if audit{"audit"}else{"population"};fs::create_dir_all(format!("{ROOT}/{run}")).unwrap();let totals=std::thread::scope(|scope|{let mut handles=vec![];for worker in 0..workers{let (ops,finalops,marks,rows,next,regs)=(&ops,&finalops,&marks,&rows,&next,&regs);handles.push(scope.spawn(move||{let mut stats:BTreeMap<(bool,usize,usize),(u64,u64,u64,u64,u64)>=BTreeMap::new();let mut out=BufWriter::new(File::create(format!("{ROOT}/{run}/events-{worker}.tsv")).unwrap());let(mut allshots,mut checks,mut badfinal,mut eventshots)=(0u64,0u64,0u64,0u64);loop{let batch=next.fetch_add(1,Ordering::SeqCst);if batch>=batches{break;}let points=&rows[batch*64..rows.len().min(batch*64+64)];let mut h=Shake256::default();h.update(b"public4b-production-fold-wire-census-20261016-fresh-MR");h.update(&(batch as u64).to_le_bytes());let mut rng=h.finalize_xof();let mut rr=rng.clone();let mut fr=rng.clone();let mut s=observed_sim::Simulator::new(nq as usize,nb as usize,&mut rng);let mut r=Simulator::new(nq as usize,nb as usize,&mut rr);let mut f=Simulator::new(fnq as usize,fnb as usize,&mut fr);for(lane,v)in points.iter().enumerate(){assert_eq!(v.batch,if audit{0}else{batch});assert_eq!(v.lane,lane);for k in 0..4{s.set_register(&regs[k],v.v[k],lane);r.set_register(&regs[k],v.v[k],lane);f.set_register(&regs[k],v.v[k],lane);}}
let mut cursor=0usize;let mut saved:BTreeMap<usize,Vec<(i128,i128,i128,i128,i128,i128)>>=BTreeMap::new();let mut events:Vec<(Mark,usize,i128,i128,i128,i128,i128)>=vec![];s.apply_observed(ops.iter(),|idx,s,_,_|{while cursor<marks.len()&&marks[cursor].at==idx{let a=&marks[cursor];if a.before{saved.insert(a.id,(0..points.len()).map(|lane|calc(&s.qubits,a,lane)).collect());}else{let values=saved.remove(&a.id).unwrap();for(lane,(expected,carry,l,e,nm,digit))in values.into_iter().enumerate(){let actual=get(&s.qubits,&a.acc,lane);assert_eq!(actual,expected,"fold formula batch={batch} lane={lane} rev={} t={} width={} L={l} E={e} Nm={nm} digit={digit}",a.rev,a.t,a.acc.len());checks+=1;if carry!=0{events.push((a.clone(),lane,carry,l,e,nm,digit));}}}cursor+=1;}});assert_eq!(cursor,marks.len());assert!(saved.is_empty());r.apply_iter(ops.iter());assert_eq!(s.qubits,r.qubits);assert_eq!(s.bits,r.bits);assert_eq!(s.phase,r.phase);assert_eq!(s.stats.toffoli_gates,r.stats.toffoli_gates);f.apply_iter(finalops.iter());let mut bad=vec![false;points.len()];for(lane,v)in points.iter().enumerate(){bad[lane]=f.get_register(&regs[0],lane)!=v.v[4]||f.get_register(&regs[1],lane)!=v.v[5];badfinal+=u64::from(bad[lane]);}let mut first=vec![true;points.len()];for(a,lane,carry,l,e,nm,digit)in events{let entry=stats.entry((a.rev,a.t,a.acc.len())).or_default();entry.0+=1;entry.1+=u64::from(carry>0);entry.2+=u64::from(carry<0);entry.3+=u64::from(bad[lane]);entry.4+=u64::from(first[lane]);eventshots+=u64::from(first[lane]);writeln!(out,"{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}",batch,lane,u8::from(a.rev),a.t,a.acc.len(),carry,l,e,nm,digit,u8::from(bad[lane]),u8::from(first[lane])).unwrap();first[lane]=false;}allshots+=points.len()as u64;if batch%64==0{eprintln!("FOLD_PROGRESS worker={worker} batch={batch}/{batches} elapsed={:.2}",started.elapsed().as_secs_f64());}}
out.flush().unwrap();let mut out=File::create(format!("{ROOT}/{run}/counts-{worker}.tsv")).unwrap();for((rev,t,w),(n,p,m,b,first))in stats{writeln!(out,"{}\t{t}\t{w}\t{n}\t{p}\t{m}\t{b}\t{first}",u8::from(rev)).unwrap();}println!("FOLD_WORKER worker={worker} shots={allshots} formula_checks={checks} full_protected_state_equal=true final_value_bad={badfinal} fold_event_shots={eventshots}");(allshots,checks,badfinal,eventshots)}));}handles.into_iter().map(|h|h.join().unwrap()).collect::<Vec<_>>()});let all=totals.iter().fold((0,0,0,0),|a,b|(a.0+b.0,a.1+b.1,a.2+b.2,a.3+b.3));println!("FOLD_CENSUS_COMPLETE shots={} formula_checks={} final_value_bad={} event_shots={} workers={workers} seconds={:.3} resource_score=NONE candidate=false",all.0,all.1,all.2,all.3,started.elapsed().as_secs_f64());}
